// Runnable demo: replication + ISR/leader election + acks=all together.
package com.bank.faulttolerance.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class FaultToleranceDemo {
    private static final Logger log = Logger.getLogger(FaultToleranceDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FaultTolerantPartition partition = new FaultTolerantPartition(
                new BrokerReplica("broker-1"),  // initial leader
                new BrokerReplica("broker-2"),
                new BrokerReplica("broker-3"));
        DurabilityManager mgr = new DurabilityManager(partition, 2); // min.insync.replicas = 2

        // Confirm a transfer with acks=all (needs >= 2 in-sync copies)
        mgr.confirmTransfer(new TransferEvent("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000")));

        // Leader broker-1 crashes -> elect from ISR, keep serving
        log.severe(() -> "broker-1 (leader) crashed");
        partition.killBroker("broker-1");
        partition.electLeaderFromIsr();
        mgr.confirmTransfer(new TransferEvent("TXF-2", "SAV2001", "CUR3001", new BigDecimal("12000")));

        // Second broker crashes -> ISR < minInSync -> reject writes (protect durability)
        log.severe(() -> "broker-2 crashed too");
        partition.killBroker("broker-2");
        mgr.confirmTransfer(new TransferEvent("TXF-3", "SAV2001", "CUR3001", new BigDecimal("3000")));
    }
}

