class FaultTolerantPartition {
    private static final Logger log = Logger.getLogger(FaultTolerantPartition.class.getName());
    private BrokerReplica leader;
    private final List<BrokerReplica> replicas = new ArrayList<>();
    FaultTolerantPartition(BrokerReplica leader, BrokerReplica... followers) {
        this.leader = leader; replicas.add(leader);
        replicas.addAll(Arrays.asList(followers));
    }
    BrokerReplica getLeader() { return leader; }
    // ISR = alive replicas (caught up); dead brokers leave the ISR
    List<BrokerReplica> isr() {
        List<BrokerReplica> isr = new ArrayList<>();
        for (BrokerReplica r : replicas) if (r.isAlive()) isr.add(r);
        return isr;
    }
    void killBroker(String id) {
        replicas.stream().filter(r -> r.getBrokerId().equals(id)).forEach(BrokerReplica::kill);
    }
    void electLeaderFromIsr() {
        List<BrokerReplica> isr = isr();
        if (isr.isEmpty()) { log.severe(() -> "No ISR replica — partition offline"); return; }
        leader = isr.get(0);
        log.info(() -> "ELECTED leader " + leader.getBrokerId() + " from ISR (no loss)");
    }
    void replicateToIsr(TransferEvent e) { for (BrokerReplica r : isr()) r.append(e); }
}

// ─── Would be in DurabilityManager.java ───
class DurabilityManager {
    private static final Logger log = Logger.getLogger(DurabilityManager.class.getName());
    private final FaultTolerantPartition partition;
    private final int minInSync;
    DurabilityManager(FaultTolerantPartition partition, int minInSync) {
        this.partition = partition; this.minInSync = minInSync;
    }
    // acks=all: confirm ONLY if ISR >= min.insync.replicas and all ISR copied it
    void confirmTransfer(TransferEvent e) {
        int isrSize = partition.isr().size();
        if (isrSize < minInSync) {
            log.severe(() -> "REJECT " + e.getTransferId() + " — ISR=" + isrSize
                    + " < min.insync.replicas=" + minInSync + " (protect durability)");
            return;
        }
        partition.replicateToIsr(e);
        log.info(() -> "CONFIRMED " + e + " acks=all (on " + isrSize + " brokers) — survives "
                + (isrSize - 1) + " more failure(s)");
    }
}

